  use Veltrion\Services\AI\Orchestrator\Enums\WorkflowState; use Veltrion\Services\AI\Context\ContextEngine; use Veltrion\Services\AI\CodeGeneration\CodeGenerator; use Veltrion\Services\AI\AIService; class WorkflowEngine { private string $workflowId; private string $currentState; private array $eventLog = []; private ContextEngine $contextEngine; private CodeGenerator $codeGenerator; private AIService $aiService; private FeatureAnalyzer $featureAnalyzer; private RiskEngine $riskEngine; private WorkflowReport $report; private int $maxRetries = 3; public function __construct(?string $workflowId = null) { $this->workflowId = $workflowId ?? 'WF-' . date('Ymd-His') . '-' . rand(1000, 9999); $this->currentState = WorkflowState::CREATED; $this->contextEngine = new ContextEngine(); $this->codeGenerator = new CodeGenerator(); $this->aiService = new AIService(); $this->featureAnalyzer = new FeatureAnalyzer(); $this->riskEngine = new RiskEngine(); $this->report = new WorkflowReport($this->workflowId); $this->logEvent(WorkflowState::CREATED, "Workflow estanciado con ID: {$this->workflowId}"); } public function getWorkflowId(): string { return $this->workflowId; } public function getCurrentState(): string { return $this->currentState; } public function transitionTo(string $newState, string $message = ''): void { $this->currentState = $newState; $this->logEvent($newState, $message); $this->persistState(); } public function logEvent(string $state, string $message): void { $this->eventLog[] = [ 'timestamp' => date('Y-m-d H:i:s'), 'state' => $state, 'message' => $message ]; $this->report->saveEventLog($this->eventLog); } private function persistState(): void { $this->report->saveState([ 'workflow_id' => $this->workflowId, 'current_state' => $this->currentState, 'event_log' => $this->eventLog, 'updated_at' => date('Y-m-d H:i:s') ]); } public function runPipeline(string $promptOrFile, string $workflowType = 'feature', array $options = []): array { $interactive = !($options['yes'] ?? f